const values = [3, 12, 3, 10, 5, 29];
const threshold = 24;
const edges = [[10, 12]];
const target = 10;
const kept = values.filter((v) => v < threshold);
const startNode = Math.max(...kept);
const adjacency = {};
function addEdge(a, b) { (adjacency[a] = adjacency[a] || []).push(b); (adjacency[b] = adjacency[b] || []).push(a); }
edges.forEach(([a, b]) => addEdge(a, b));
const visited = new Set([startNode]);
const queue = [startNode];
let found = startNode === target;
while (queue.length && !found) {
  const node = queue.shift();
  for (const next of (adjacency[node] || [])) {
    if (next === target) { found = true; break; }
    if (!visited.has(next)) { visited.add(next); queue.push(next); }
  }
}
return 'Starting node: ' + startNode + '. A path to node ' + target + (found ? ' exists.' : ' does not exist.');
