function subsets(arr) { return arr.reduce((acc, item) => acc.concat(acc.map((s) => s.concat(item))), [[]]); }
const allSubsets = subsets(groups).filter((s) => s.length > 0);
function seatSum(s) { return s.reduce((sum, g) => sum + seats[g], 0); }
const winning = allSubsets.filter((s) => seatSum(s) >= threshold);
const minimalWinning = winning.filter((s) => s.every((member) => seatSum(s.filter((g) => g !== member)) < threshold));
const labels = minimalWinning.map((s) => s.join(''));
return 'Minimal winning coalitions: ' + labels.join(', ') + '.';
